const input = $json;

// ======================================================
// 1. Récupération des paramètres
// ======================================================

const service =
  input.service ??
  input.query?.service ??
  null;

const site =
  input.site ??
  input.query?.site ??
  null;

const dateDebut =
  input.dateDebut ??
  input.query?.dateDebut ??
  null;

const dateFin =
  input.dateFin ??
  input.query?.dateFin ??
  null;

// ======================================================
// 2. Vérification présence
// ======================================================

if (!service) {
  throw new Error(
    'Paramètre "service" manquant'
  );
}

if (!site) {
  throw new Error(
    'Paramètre "site" manquant'
  );
}

if (!dateDebut) {
  throw new Error(
    'Paramètre "dateDebut" manquant'
  );
}

if (!dateFin) {
  throw new Error(
    'Paramètre "dateFin" manquant'
  );
}

// ======================================================
// 3. Normalisation
// ======================================================

const serviceNormalized =
  String(service)
    .trim()
    .toUpperCase();

const siteNormalized =
  String(site)
    .trim()
    .toUpperCase();

const dateDebutNormalized =
  String(dateDebut)
    .trim();

const dateFinNormalized =
  String(dateFin)
    .trim();

// ======================================================
// 4. Validation service
// Exemples acceptés :
// PASSEPORT
// VISA
// ETAT_CIVIL
// LEGALISATION
// ======================================================

if (
  !/^[A-Z_]{2,30}$/.test(
    serviceNormalized
  )
) {
  throw new Error(
    `Paramètre service invalide : ${serviceNormalized}`
  );
}

// ======================================================
// 5. Validation site
// Exemples :
// PARIS
// LYON
// BORDEAUX
// ======================================================

if (
  !/^[A-Z_]{2,30}$/.test(
    siteNormalized
  )
) {
  throw new Error(
    `Paramètre site invalide : ${siteNormalized}`
  );
}

// ======================================================
// 6. Validation format des dates
// ======================================================

const dateRegex =
  /^\d{4}-\d{2}-\d{2}$/;

if (
  !dateRegex.test(
    dateDebutNormalized
  )
) {
  throw new Error(
    `Paramètre dateDebut invalide : ${dateDebutNormalized}`
  );
}

if (
  !dateRegex.test(
    dateFinNormalized
  )
) {
  throw new Error(
    `Paramètre dateFin invalide : ${dateFinNormalized}`
  );
}

// ======================================================
// 7. Validation réelle des dates
// ======================================================

function isValidDate(value) {
  const d =
    new Date(
      `${value}T00:00:00Z`
    );

  return (
    !Number.isNaN(d.getTime()) &&
    d.toISOString().slice(0, 10) === value
  );
}

if (
  !isValidDate(
    dateDebutNormalized
  )
) {
  throw new Error(
    `dateDebut n'est pas une date valide : ${dateDebutNormalized}`
  );
}

if (
  !isValidDate(
    dateFinNormalized
  )
) {
  throw new Error(
    `dateFin n'est pas une date valide : ${dateFinNormalized}`
  );
}

// ======================================================
// 8. Vérifier ordre des dates
// ======================================================

const start =
  new Date(
    `${dateDebutNormalized}T00:00:00Z`
  );

const end =
  new Date(
    `${dateFinNormalized}T00:00:00Z`
  );

if (
  start.getTime() >
  end.getTime()
) {
  throw new Error(
    `dateDebut (${dateDebutNormalized}) doit être antérieure ou égale à dateFin (${dateFinNormalized})`
  );
}

// ======================================================
// 9. Résultat final
// ======================================================

return [{
  json: {

    service:
      serviceNormalized,

    site:
      siteNormalized,

    dateDebut:
      dateDebutNormalized,

    dateFin:
      dateFinNormalized,

    // utile pendant les tests
    validationDebug: {

      serviceSource:
        input.service !== undefined
          ? 'direct'
          : input.query?.service !== undefined
            ? 'query'
            : null,

      siteSource:
        input.site !== undefined
          ? 'direct'
          : input.query?.site !== undefined
            ? 'query'
            : null,

      dateDebutSource:
        input.dateDebut !== undefined
          ? 'direct'
          : input.query?.dateDebut !== undefined
            ? 'query'
            : null,

      dateFinSource:
        input.dateFin !== undefined
          ? 'direct'
          : input.query?.dateFin !== undefined
            ? 'query'
            : null
    }
  }
}];

const x = $json;

const slots =
  Array.isArray(x.slots)
    ? x.slots
    : [];

const count =
  Number(x.count ?? slots.length);

return [{
  json: {
    success: true,
    count,
    slots
  }
}];
